// Reads your metrics endpoint when metricsUrl is set; otherwise falls back to
// the bundled demo dataset so the template demos with ZERO external services.
// Contract (one customer per run):
//   { "userName", "monthLabel", "highlight", "stats": [{ "label", "value", "delta" }] }
// Stats may also be strings like "Videos rendered: 48 (+12)" — they are parsed.
const cfg = $('Config').first().json;

const DEMO = {
  userName: 'Maya',
  monthLabel: 'July 2026',
  highlight: 'Your best month yet — July doubled your June output.',
  stats: [
    { label: 'Videos rendered', value: '48', delta: '+12 vs last month' },
    { label: 'Watch time', value: '3.2h', delta: '+0.8h vs last month' },
    { label: 'Top video', value: 'Product teaser v2', delta: '' },
    { label: 'Credits used', value: '1,240', delta: '' },
  ],
};

const hasEndpoint = String(cfg.metricsUrl || '').trim() !== '';
let raw = null;
if (hasEndpoint) {
  try { raw = $('Fetch metrics').first().json; } catch (e) { raw = null; }
  if (Array.isArray(raw)) raw = raw[0]; // arrays are accepted; the first entry wins
  if (!raw || typeof raw !== 'object') {
    throw new Error('metricsUrl returned no usable JSON object. Expected { userName, monthLabel, highlight, stats: [{ label, value, delta }] }.');
  }
} else {
  raw = DEMO;
}

// "Label: value (+delta)" strings are coerced into objects so sheet-shaped
// sources work without a mapping step.
const parseStat = (s) => {
  if (s && typeof s === 'object') return { label: s.label, value: s.value, delta: s.delta || '' };
  const m = /^(.+?):\s*(.+?)(?:\s*\((.+?)\))?$/.exec(String(s || '').trim());
  return m ? { label: m[1], value: m[2], delta: m[3] || '' } : null;
};

const stats = (Array.isArray(raw.stats) ? raw.stats : []).map(parseStat).filter(Boolean);
if (hasEndpoint && !stats.length) {
  // A configured endpoint that returns junk must FAIL the run — never silently
  // send a real customer the demo numbers.
  throw new Error('The metrics payload has no usable stats — each entry needs { label, value }.');
}

let monthLabel = String(raw.monthLabel || '').trim();
if (!monthLabel) {
  // A recap that runs on the 1st covers the month that just ended.
  const d = new Date();
  d.setDate(1);
  d.setMonth(d.getMonth() - 1);
  monthLabel = d.toLocaleString('en-US', { month: 'long', year: 'numeric' });
}

return [{ json: {
  userName: String(raw.userName || '').trim(),
  monthLabel,
  highlight: String(raw.highlight || '').trim(),
  stats,
  usedDemoData: !hasEndpoint,
} }];

'use strict';
// Builds the Zvid project JSON for the Wrapped-style month-in-review video.
// Design adapted from the "apppersonal-progress-report" example (cream canvas,
// teal/coral accents, pill badges, SVG progress bar) with the one-stat-per-scene
// beat structure of "dataviz-monthly-report" / "ai-report-summary".
//
// buildProject(config, data) -> { payload, meta }
//   config: the Config node JSON (brand, colours, fonts, timings, music).
//   data:   { userName, monthLabel, highlight, stats:[{label,value,delta}], usedDemoData }

const round = (n) => Math.round(n * 100) / 100;

const escapeHtml = (s) =>
  String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  }[c]));

function hexToRgb(hex) {
  const h = String(hex).replace('#', '');
  const v = h.length === 3 ? h.split('').map((c) => c + c).join('') : h;
  const n = parseInt(v, 16);
  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
}

const rgba = (hex, a) => {
  const { r, g, b } = hexToRgb(hex);
  return `rgba(${r},${g},${b},${a})`;
};

// f > 0 lightens toward white, f < 0 darkens toward black. Used to derive the
// outro gradient from the single brand accent, the way the source example
// hand-picked #12B7A3/#0B7E70 around its #0E9F8E accent.
function shade(hex, f) {
  const { r, g, b } = hexToRgb(hex);
  const t = f < 0 ? 0 : 255;
  const p = Math.abs(f);
  const c = (v) => Math.round(v + (t - v) * p);
  const to2 = (v) => v.toString(16).padStart(2, '0');
  return `#${to2(c(r))}${to2(c(g))}${to2(c(b))}`;
}

// The hero number must stay huge for "48" but survive "9,999,999" and even a
// sentence-length value ("Top video: ..."), so type size follows length.
function valueStyle(value) {
  const len = String(value).length;
  if (len <= 3) return { size: 230, ls: -8, lh: 0.95, mt: 14 };
  if (len <= 6) return { size: 190, ls: -6, lh: 0.95, mt: 14 };
  if (len <= 9) return { size: 148, ls: -4, lh: 0.95, mt: 18 };
  if (len <= 14) return { size: 104, ls: -2, lh: 1, mt: 24 };
  if (len <= 28) return { size: 72, ls: -1, lh: 1.1, mt: 26 };
  return { size: 56, ls: 0, lh: 1.18, mt: 28 };
}

// "+12" -> "▲ +12", "-3%" -> "▼ -3%", anything already arrowed passes through.
function deltaDisplay(delta) {
  const d = String(delta || '').trim();
  if (!d) return null;
  if (/^[▲▼]/.test(d)) return d;
  if (/^\+/.test(d)) return `▲ ${d}`;
  if (/^[-−]/.test(d)) return `▼ ${d}`;
  return d;
}

function buildProject(config, data) {
  const cfg = config || {};
  const accent = cfg.accent || '#0E9F8E';
  const accent2 = cfg.accent2 || '#F26A4B';
  const bg = cfg.background || '#F3F0EA';
  const ink = cfg.ink || '#1E241F';
  const muted = cfg.muted || '#6B6459';
  const displayFont = cfg.displayFont || 'Outfit';
  const labelFont = cfg.labelFont || 'Space Grotesk';
  const brandName = String(cfg.brandName || 'Relay').trim();
  const ctaText = String(cfg.ctaText || 'See you next month').trim();

  const introD = Number(cfg.introSeconds ?? 3.4);
  const statD = Number(cfg.statSeconds ?? 2.8);
  const outroD = Number(cfg.outroSeconds ?? 4);
  const tDur = Number(cfg.transitionSeconds ?? 0.45);

  const userName = String((data && data.userName) || '').trim() || 'friend';
  const monthLabel = String((data && data.monthLabel) || '').trim() || 'This month';
  const highlight = String((data && data.highlight) || '').trim();

  const stats = (Array.isArray(data && data.stats) ? data.stats : [])
    .map((s) => ({
      label: String((s && s.label) || '').trim(),
      value: String((s && s.value) == null ? '' : s.value).trim(),
      delta: String((s && s.delta) || '').trim(),
    }))
    .filter((s) => s.label && s.value)
    .slice(0, Number(cfg.maxStats ?? 4));
  if (!stats.length) {
    throw new Error('No stats to feature — the metrics data needs at least one { label, value }.');
  }
  const n = stats.length;

  const kickerLine = escapeHtml(`${userName} · ${monthLabel}`.toUpperCase());

  // ---- intro ------------------------------------------------------------
  const introVisuals = [];
  if (cfg.introImage) {
    introVisuals.push({
      type: 'IMAGE', src: cfg.introImage, width: 1080, height: 1920,
      position: 'center-center', resize: 'cover', zoom: true, opacity: 0.35,
      track: 0, enterBegin: 0, exitEnd: introD,
    });
  }
  introVisuals.push({
    type: 'SVG', width: 1080, height: 1920, track: 1, enterBegin: 0, exitEnd: introD,
    svg: `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><linearGradient id='mirIntro' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='${bg}' stop-opacity='0.9'/><stop offset='0.5' stop-color='${bg}' stop-opacity='0.55'/><stop offset='1' stop-color='${bg}' stop-opacity='0.95'/></linearGradient></defs><rect width='1080' height='1920' fill='url(#mirIntro)'/></svg>`,
  });
  introVisuals.push({
    type: 'TEXT', x: 540, y: 740, anchor: 'top-center', track: 2,
    enterBegin: 0.2, enterEnd: 0.65, enterAnimation: 'fade', exitEnd: introD,
    style: { fontFamily: labelFont },
    html: `<div style='display:inline-block; background:${rgba(accent, 0.14)}; color:${accent}; border-radius:999px; padding:12px 32px; font-size:26px; font-weight:700; letter-spacing:4px;'>${escapeHtml(brandName.toUpperCase())} · MONTH IN REVIEW</div>`,
  });
  const monthSize = monthLabel.length > 12 ? 96 : 118;
  introVisuals.push({
    type: 'TEXT', x: 540, y: 850, width: 900, anchor: 'top-center', track: 3,
    enterBegin: 0.45, enterEnd: 0.95, enterAnimation: 'smoothup', exitEnd: introD,
    style: { fontFamily: displayFont },
    html: `<div style='text-align:center; color:${ink}; font-size:${monthSize}px; line-height:1; font-weight:800; letter-spacing:-3px;'>${escapeHtml(monthLabel)}</div><div style='margin-top:24px; text-align:center; color:${muted}; font-size:34px; font-weight:500;'>Made for ${escapeHtml(userName)}</div>`,
  });

  const scenes = [{
    id: 'intro', duration: introD, backgroundColor: bg,
    transition: 'smoothleft', transitionId: 'stat-1', transitionDuration: tDur,
    visuals: introVisuals,
  }];

  // ---- one scene per stat ------------------------------------------------
  stats.forEach((stat, i) => {
    const isLast = i === n - 1;
    // The progress bar fills a little more with every beat — the month
    // "filling up" as the recap plays.
    const frac = n === 1 ? 0.9 : round(0.42 + 0.53 * (i / (n - 1)));
    const barW = Math.round(780 * frac);
    const knobX = 150 + barW;

    const circles = i % 2 === 0
      ? `<circle cx='880' cy='300' r='140' fill='${rgba(accent2, 0.1)}'/><circle cx='170' cy='1560' r='180' fill='${rgba(accent, 0.1)}'/>`
      : `<circle cx='200' cy='280' r='150' fill='${rgba(accent, 0.1)}'/><circle cx='900' cy='1600' r='170' fill='${rgba(accent2, 0.1)}'/>`;

    const vs = valueStyle(stat.value);
    const delta = deltaDisplay(stat.delta);

    const visuals = [
      {
        type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: statD,
        svg: `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><rect width='1080' height='1920' fill='${bg}'/>${circles}</svg>`,
      },
      {
        type: 'SVG', width: 1080, height: 1920, track: 1,
        enterBegin: 0.45, enterEnd: 0.95, enterAnimation: 'fade', exitEnd: statD,
        svg: `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><rect x='150' y='1160' width='780' height='52' rx='26' fill='${rgba(ink, 0.08)}'/><rect x='150' y='1160' width='${barW}' height='52' rx='26' fill='${accent}'/><rect x='150' y='1160' width='${barW}' height='26' rx='13' fill='rgba(255,255,255,0.25)'/><circle cx='${knobX}' cy='1186' r='36' fill='${accent}' stroke='${bg}' stroke-width='6'/></svg>`,
      },
      {
        type: 'TEXT', x: 540, y: 380, width: 920, anchor: 'top-center', track: 2,
        enterBegin: 0.1, enterEnd: 0.5, enterAnimation: 'fade', exitEnd: statD,
        style: { fontFamily: labelFont },
        html: `<div style='text-align:center; color:${muted}; font-size:26px; line-height:1.5; font-weight:700; letter-spacing:5px;'>${kickerLine}</div>`,
      },
      {
        type: 'TEXT', x: 540, y: 560, width: 880, anchor: 'top-center', track: 3,
        enterBegin: 0.2, enterEnd: 0.65, enterAnimation: 'circleopen', exitEnd: statD,
        style: { fontFamily: displayFont },
        html: `<div style='text-align:center; color:${accent2}; font-size:31px; line-height:1.35; font-weight:700; letter-spacing:4px;'>${escapeHtml(stat.label.toUpperCase())}</div><div style='margin-top:${vs.mt}px; text-align:center; color:${ink}; font-size:${vs.size}px; line-height:${vs.lh}; font-weight:800; letter-spacing:${vs.ls}px;'>${escapeHtml(stat.value)}</div>`,
      },
    ];

    if (delta) {
      visuals.push({
        type: 'TEXT', x: 540, y: 1005, anchor: 'top-center', track: 4,
        enterBegin: 0.5, enterEnd: 0.95, enterAnimation: 'smoothright', exitEnd: statD,
        style: { fontFamily: labelFont },
        html: `<div style='display:inline-block; background:${accent2}; color:#FFFFFF; border-radius:999px; padding:14px 34px; font-size:29px; font-weight:800;'>${escapeHtml(delta)}</div>`,
      });
    }

    visuals.push({
      type: 'TEXT', x: 540, y: 1300, anchor: 'top-center', track: 5,
      enterBegin: 0.55, enterEnd: 0.95, enterAnimation: 'fade', exitEnd: statD,
      style: { fontFamily: labelFont },
      html: `<div style='text-align:center; color:${rgba(ink, 0.45)}; font-size:27px; font-weight:700; letter-spacing:6px;'>${String(i + 1).padStart(2, '0')} / ${String(n).padStart(2, '0')}</div>`,
    });

    scenes.push({
      id: `stat-${i + 1}`, duration: statD, backgroundColor: bg,
      transition: isLast ? 'smoothup' : 'smoothleft',
      transitionId: isLast ? 'outro' : `stat-${i + 2}`,
      transitionDuration: tDur,
      visuals,
    });
  });

  // ---- outro -------------------------------------------------------------
  const gradTop = shade(accent, 0.12);
  const gradBottom = shade(accent, -0.28);
  const nameSize = userName.length <= 10 ? 84 : userName.length <= 16 ? 72 : 58;

  const outroVisuals = [
    {
      type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: outroD,
      svg: `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><radialGradient id='mirEnd' cx='0.5' cy='0.4' r='0.95'><stop offset='0' stop-color='${gradTop}'/><stop offset='1' stop-color='${gradBottom}'/></radialGradient></defs><rect width='1080' height='1920' fill='url(#mirEnd)'/><circle cx='540' cy='600' r='140' fill='none' stroke='rgba(255,255,255,0.6)' stroke-width='3'/><path d='M540 500 L563 577 L640 600 L563 623 L540 700 L517 623 L440 600 L517 577 Z' fill='#FFFFFF'/></svg>`,
    },
    {
      type: 'TEXT', x: 540, y: 850, width: 920, anchor: 'top-center', track: 1,
      enterBegin: 0.25, enterEnd: 0.75, enterAnimation: 'smoothup', exitEnd: outroD,
      style: { fontFamily: displayFont },
      html: `<div style='text-align:center; color:#FFFFFF; font-size:${nameSize}px; line-height:1.08; font-weight:800; letter-spacing:-2px;'>That&#39;s a wrap,<br>${escapeHtml(userName)}.</div>`,
    },
  ];
  if (highlight) {
    outroVisuals.push({
      type: 'TEXT', x: 540, y: 1100, width: 860, anchor: 'top-center', track: 2,
      enterBegin: 0.55, enterEnd: 1, enterAnimation: 'smoothup', exitEnd: outroD,
      style: { fontFamily: displayFont },
      html: `<div style='text-align:center; color:rgba(255,255,255,0.92); font-size:38px; line-height:1.45; font-weight:500;'>${escapeHtml(highlight)}</div>`,
    });
  }
  outroVisuals.push({
    type: 'TEXT', x: 540, y: 1420, anchor: 'top-center', track: 3,
    enterBegin: 0.8, enterEnd: 1.25, enterAnimation: 'circleopen', exitEnd: outroD,
    style: { fontFamily: labelFont },
    html: `<div style='display:inline-block; background:#FFFFFF; color:${gradBottom}; border-radius:999px; padding:24px 58px; font-size:36px; font-weight:800;'>${escapeHtml(ctaText)}</div>`,
  });
  outroVisuals.push({
    type: 'TEXT', x: 540, y: 1580, anchor: 'top-center', track: 4,
    enterBegin: 1.1, enterEnd: 1.5, enterAnimation: 'fade', exitEnd: outroD,
    style: { fontFamily: labelFont },
    html: `<div style='text-align:center; color:rgba(255,255,255,0.75); font-size:26px; font-weight:700; letter-spacing:5px;'>${escapeHtml(brandName.toUpperCase())}</div>`,
  });

  scenes.push({ id: 'outro', duration: outroD, backgroundColor: gradBottom, visuals: outroVisuals });

  // ---- audio + assembly --------------------------------------------------
  const audios = [];
  if (cfg.includeMusic !== false && cfg.musicUrl) {
    // NOTE: no `track` here — the live API rejects audios[].track even though
    // some library examples carry it. A single music bed does not need one.
    audios.push({ src: cfg.musicUrl, volume: Number(cfg.musicVolume ?? 0.15) });
  }

  const transitionsOverlap = tDur * (scenes.length - 1);
  const totalDurationSec = round(scenes.reduce((sum, s) => sum + s.duration, 0) - transitionsOverlap);

  const name = (`${monthLabel}-in-review-${userName}`
    .toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60)) || 'month-in-review';

  const payload = {
    name,
    resolution: cfg.resolution || 'instagram-reel',
    frameRate: Number(cfg.frameRate ?? 30),
    backgroundColor: bg,
    outputFormat: 'mp4',
    scenes,
    ...(audios.length ? { audios } : {}),
  };

  const meta = {
    userName,
    monthLabel,
    statCount: n,
    sceneCount: scenes.length,
    totalDurationSec,
    usedDemoData: Boolean(data && data.usedDemoData),
  };

  return { payload, meta };
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { buildProject };
}

// ---- n8n glue -----------------------------------------------------------
const cfg = $('Config').first().json;
const data = $input.first().json;
const { payload, meta } = buildProject(cfg, data);
return [{ json: { payload, meta } }];

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug — surface the field list instead of a
// generic HTTP error.
const res = $input.first().json;
const status = res.statusCode ?? (res.valid === true ? 200 : 400);
const body = res.body || { ...res, details: res.errors ?? res.details };

if (status !== 200 || body.valid === false) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => `  - ${d.field}: ${d.message}`).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error(`Zvid rejected the project (HTTP ${status}): ${body.message || body.error}\n${details}`);
}

const build = $('Build project JSON').first().json;
return [{
  json: {
    ...build,
    creditsRequired: body.creditsRequired,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
  },
}];

// Fails fast on a failed render and stops the poll loop from running forever.
const cfg = $('Config').first().json;
const job = $input.first().json;

if (job.state === 'failed') {
  throw new Error('Render failed: ' + (job.failedReason || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error(`Render did not finish within ${cfg.timeoutMinutes} minutes (job ${job.id}, state ${job.state}).`);
}

return $input.all();

// Final report for the run.
const cfg = $('Config').first().json;
const build = $('Check validation').first().json;
const job = $('Get render status').first().json;
const url = typeof job.result === 'string' ? job.result : (job.result && job.result.url) || null;

// The email step is best-effort; report where the link actually went.
let emailedTo = null;
try {
  const e = $('Email the video').first().json;
  if (e && e.error === undefined) emailedTo = cfg.emailTo;
} catch (err) { /* email branch skipped */ }

return [{
  json: {
    dryRun: false,
    userName: build.meta.userName,
    monthLabel: build.meta.monthLabel,
    usedDemoData: build.meta.usedDemoData,
    videoUrl: url,
    editorLink: null,
    jobId: job.id,
    creditsCharged: build.creditsRequired,
    videoSeconds: build.meta.totalDurationSec,
    statCount: build.meta.statCount,
    emailedTo,
  },
}];

// Dry run: everything except the paid render. Open editorLink to preview the
// draft, then set dryRun to false in Config to render for real.
const cfg = $('Config').first().json;
const d = $('Check validation').first().json;

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the rest of the dry-run report.
let editorLink = null;
let draftId = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = `${String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '')}/?project=${project.id}`;
  }
} catch (e) { /* draft step skipped or failed */ }

return [{
  json: {
    dryRun: true,
    userName: d.meta.userName,
    monthLabel: d.meta.monthLabel,
    usedDemoData: d.meta.usedDemoData,
    statCount: d.meta.statCount,
    videoSeconds: d.meta.totalDurationSec,
    creditsRequired: d.creditsRequired,
    warnings: d.warnings,
    editorLink,
    draftId,
    videoUrl: null,
    nextStep: editorLink
      ? 'Open editorLink to preview the draft. Set dryRun to false in Config to render.'
      : 'Set dryRun to false in Config to render this for real.',
    payload: d.payload,
  },
}];
